# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KOROZYON (METALİK AŞINMA) VE DEMİRİN PASLANMA MEKANİZMASI</text>\n  <rect x="25" y="46" width="315" height="196" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="182" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#991b1b">Korozyonun Elektrokimyasal Temeli</text>\n  <text x="42" y="96" font-size="11.5" fill="#7f1d1d">• Metallerin ve alaşımların çevredeki <tspan font-weight="bold">oksijen, nem (su),</tspan></text>\n  <text x="50" y="112" font-size="11.5" fill="#7f1d1d"><tspan font-weight="bold">asit veya tuzlu çözeltilerle</tspan> kendiliğinden</text>\n  <text x="50" y="128" font-size="11.5" fill="#7f1d1d"><tspan font-weight="bold">yükseltgenerek (elektron kaybederek)</tspan> aşınmasıdır.</text>\n  <text x="42" y="152" font-size="11.5" fill="#7f1d1d">• <tspan font-weight="bold">Gümüşün</tspan> kararması, <tspan font-weight="bold">bakırın</tspan> yeşil tabaka bağlaması,</text>\n  <text x="50" y="168" font-size="11.5" fill="#7f1d1d"><tspan font-weight="bold">demirin paslanması</tspan> korozyon örnekleridir.</text>\n  <rect x="42" y="184" width="280" height="44" rx="6" fill="#ffffff" stroke="#f87171"/>\n  <text x="182" y="203" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">Aktifliği yüksek olan metaller</text>\n  <text x="182" y="219" text-anchor="middle" font-size="10.5" fill="#7f1d1d">korozyona daha hızlı ve kolay uğrar!</text>\n  <rect x="360" y="46" width="315" height="196" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="517" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">Demirin Paslanma Tepkimeleri</text>\n  <rect x="378" y="84" width="280" height="40" rx="6" fill="#ffffff" stroke="#f59e0b"/>\n  <text x="388" y="101" font-size="11" font-weight="bold" fill="#b45309">Anot (Yükseltgenme):</text>\n  <text x="388" y="117" font-size="11" fill="#78350f">Fe(k) → Fe²⁺(suda) + 2e⁻</text>\n  <rect x="378" y="132" width="280" height="40" rx="6" fill="#ffffff" stroke="#f59e0b"/>\n  <text x="388" y="149" font-size="11" font-weight="bold" fill="#b45309">Katot (İndirgenme):</text>\n  <text x="388" y="165" font-size="11" fill="#78350f">1/2 O₂(g) + H₂O(s) + 2e⁻ → 2OH⁻(suda)</text>\n  <rect x="378" y="180" width="280" height="48" rx="6" fill="#ffffff" stroke="#f59e0b"/>\n  <text x="388" y="198" font-size="11" font-weight="bold" fill="#15803d">Pas Oluşumu (Fe₂O₃ · nH₂O):</text>\n  <text x="388" y="216" font-size="10.5" fill="#78350f">Nemli hava + tuzlu su paslanmayı çok hızlandırır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KOROZYONDAN KORUNMA YÖNTEMLERİ VE KURBAN ELEKTROT</text>\n  <rect x="25" y="46" width="295" height="196" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="172" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Fiziksel ve Kimyasal Yöntemler</text>\n  <text x="40" y="96" font-size="11.5" fill="#1e3a8a">1. <tspan font-weight="bold">Boyama ve Yağlama:</tspan> Metalin hava (O₂)</text>\n  <text x="52" y="112" font-size="11" fill="#1e3a8a">ve su (nem) ile temasını keser.</text>\n  <text x="40" y="136" font-size="11.5" fill="#1e3a8a">2. <tspan font-weight="bold">Galvanize Etme:</tspan> Demirin erimiş veya</text>\n  <text x="52" y="152" font-size="11" fill="#1e3a8a">elektrolitik <tspan font-weight="bold">çinko (Zn)</tspan> tabakasıyla kaplanması.</text>\n  <text x="40" y="176" font-size="11.5" fill="#1e3a8a">3. <tspan font-weight="bold">Elektrolizle Metal Kaplama:</tspan> Krom, nikel,</text>\n  <text x="52" y="192" font-size="11" fill="#1e3a8a">kalay veya altın ile yüzeyin kaplanması.</text>\n  <text x="40" y="216" font-size="11.5" fill="#1e3a8a">4. <tspan font-weight="bold">Paslanmaz Çelik (Alaşım):</tspan> Fe + Cr + Ni.</text>\n  <rect x="340" y="46" width="335" height="196" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="507" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">Katodik Koruma (Kurban Elektrot İlkesi)</text>\n  <rect x="360" y="88" width="130" height="54" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="425" y="110" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">KURBAN ELEKTROT</text>\n  <text x="425" y="128" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">ANOT (Mg, Zn, Al)</text>\n  <rect x="530" y="88" width="125" height="54" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="592" y="110" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">KORUNAN METAL</text>\n  <text x="592" y="128" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">KATOT (Demir / Fe)</text>\n  <line x1="490" y1="115" x2="530" y2="115" stroke="#dc2626" stroke-width="3"/>\n  <text x="510" y="106" text-anchor="middle" font-size="11" font-weight="bold" fill="#dc2626">e⁻ →</text>\n  <text x="358" y="164" font-size="11" fill="#14532d">• Korunacak metale (Fe), aktifliği ondan <tspan font-weight="bold">daha yüksek</tspan></text>\n  <text x="366" y="180" font-size="11" fill="#14532d">bir metal (Mg, Zn, Al) bağlanır (Aktiflik: Mg &gt; Al &gt; Zn &gt; Fe).</text>\n  <text x="358" y="202" font-size="11" fill="#14532d">• Aktif metal <tspan font-weight="bold">anot</tspan> olup yükseltgenerek aşınır; korunan</text>\n  <text x="366" y="218" font-size="11" fill="#14532d">demir ise <tspan font-weight="bold">katot</tspan> yapılarak paslanmaktan kurtulur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">1. ÜNİTE ÖZET KARŞILAŞTIRMASI: GALVANİK HÜCRE VE ELEKTROLİZ</text>\n  <rect x="25" y="48" width="315" height="192" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Galvanik Hücre (Elektrokimyasal Pil)</text>\n  <text x="42" y="96" font-size="11.5" fill="#1e3a8a">• Kimyasal enerjiyi elektrik enerjisine çevirir.</text>\n  <text x="42" y="118" font-size="11.5" fill="#1e3a8a">• Kendiliğinden gerçekleşir (<tspan font-weight="bold">E°_hücre &gt; 0</tspan>, istemli).</text>\n  <text x="42" y="140" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">Anot (-):</tspan> Aktifliği büyük metal (Yükseltgenme).</text>\n  <text x="42" y="162" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">Katot (+):</tspan> Aktifliği küçük metal (İndirgenme).</text>\n  <rect x="42" y="180" width="280" height="44" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="182" y="200" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Nernst: E = E° - (0,0592 / n) · log([Anot]/[Katot])</text>\n  <text x="182" y="216" text-anchor="middle" font-size="10.5" fill="#1e3a8a">Tuz köprüsü: Anyonlar anoda, katyonlar katoda</text>\n  <rect x="360" y="48" width="315" height="192" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="517" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">Elektroliz Hücresi ve Faraday Yasası</text>\n  <text x="378" y="96" font-size="11.5" fill="#581c87">• Elektrik enerjisini kimyasal enerjiye çevirir.</text>\n  <text x="378" y="118" font-size="11.5" fill="#581c87">• İstemsiz redokstur (<tspan font-weight="bold">E° &lt; 0</tspan>), dış üreteçle yürür.</text>\n  <text x="378" y="140" font-size="11.5" fill="#581c87">• <tspan font-weight="bold">Anot (+):</tspan> Yükseltgenme (Anyonlar gider).</text>\n  <text x="378" y="162" font-size="11.5" fill="#581c87">• <tspan font-weight="bold">Katot (-):</tspan> İndirgenme (Katyonlar gider).</text>\n  <rect x="378" y="180" width="280" height="44" rx="6" fill="#ffffff" stroke="#c084fc"/>\n  <text x="517" y="200" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">Faraday: Q = I · t   ve   m = (Q / 96500) · (M_A / z)</text>\n  <text x="517" y="216" text-anchor="middle" font-size="10.5" fill="#581c87">1 Faraday = 1 mol e⁻ = 96500 Coulomb</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
